{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let names = null
const seen = new Set()
const ballots = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (names !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    names = []
    for (const name of t.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
      names.push(name)
    }
  } else if (t[0] === 'ballot') {
    if (names === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const used = new Set()
    for (const name of t.slice(2)) {
      if (!seen.has(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (used.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      used.add(name)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
})
if (names === null) fail('error: no candidates')

const continuing = new Set(names)
const history = new Map(names.map((c) => [c, []]))
const out = []
let roundCount = 0
let result = 'no winner'
for (;;) {
  roundCount++
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  for (const c of continuing) history.get(c).push(counts.get(c))
  const listed = [...continuing].sort((a, b) => (counts.get(a) > counts.get(b) ? -1 : counts.get(a) < counts.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
  let line = `round ${roundCount}: ` + listed.map((c) => `${c}=${counts.get(c)}`).join(' ')
  line += ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const win = listed.find((c) => counts.get(c) * 2n > active)
  if (win !== undefined) {
    result = `winner ${win}`
    break
  }
  let s = listed.slice()
  let min = s.reduce((m, c) => (counts.get(c) < m ? counts.get(c) : m), counts.get(s[0]))
  s = s.filter((c) => counts.get(c) === min)
  for (let r = 0; s.length > 1 && r < roundCount; r++) {
    const m = s.reduce((a, c) => (history.get(c)[r] < a ? history.get(c)[r] : a), history.get(s[0])[r])
    const k = s.filter((c) => history.get(c)[r] === m)
    if (k.length < s.length) {
      s = k
      r = -1
    }
  }
  const elim = s.reduce((a, c) => (c > a ? c : a))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
out.push(result)
if (mode === 'tally') process.stdout.write(`rounds ${roundCount}\n${result}\n`)
else process.stdout.write(out.join('\n') + '\n')
EOF
